class Solution {
public:
    int minAreaRect(vector<vector<int>>& points) {
        unordered_set<long long> pt_set;
        for (const auto& p : points) {
            pt_set.insert(((long long)p[0] << 32) | (unsigned int)p[1]);
        }
        int min_area = INT_MAX;
        int n = points.size();
        for (int i = 0; i < n; ++i) {
            int x1 = points[i][0], y1 = points[i][1];
            for (int j = i + 1; j < n; ++j) {
                int x2 = points[j][0], y2 = points[j][1];
                if (x1 != x2 && y1 != y2) {
                    long long p3 = ((long long)x1 << 32) | (unsigned int)y2;
                    long long p4 = ((long long)x2 << 32) | (unsigned int)y1;
                    if (pt_set.count(p3) && pt_set.count(p4)) {
                        int area = abs(x1 - x2) * abs(y1 - y2);
                        min_area = min(min_area, area);
                    }
                }
            }
        }
        return min_area == INT_MAX ? 0 : min_area;
    }
};

class Solution {
    public int minAreaRect(int[][] points) {
        Set<Long> set = new HashSet<>();
        for (int[] p : points) {
            set.add(((long) p[0] << 32) | (p[1] & 0xFFFFFFFFL));
        }
        int minArea = Integer.MAX_VALUE;
        int n = points.length;
        for (int i = 0; i < n; i++) {
            int x1 = points[i][0], y1 = points[i][1];
            for (int j = i + 1; j < n; j++) {
                int x2 = points[j][0], y2 = points[j][1];
                if (x1 != x2 && y1 != y2) {
                    long p3 = ((long) x1 << 32) | (y2 & 0xFFFFFFFFL);
                    long p4 = ((long) x2 << 32) | (y1 & 0xFFFFFFFFL);
                    if (set.contains(p3) && set.contains(p4)) {
                        int area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
                        minArea = Math.min(minArea, area);
                    }
                }
            }
        }
        return minArea == Integer.MAX_VALUE ? 0 : minArea;
    }
}

var minAreaRect = function(points) {
    const set = new Set();
    for (const [x, y] of points) {
        set.add(x + ',' + y);
    }
    let minArea = Infinity;
    const n = points.length;
    for (let i = 0; i < n; i++) {
        const [x1, y1] = points[i];
        for (let j = i + 1; j < n; j++) {
            const [x2, y2] = points[j];
            if (x1 !== x2 && y1 !== y2) {
                if (set.has(x1 + ',' + y2) && set.has(x2 + ',' + y1)) {
                    const area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
                    minArea = Math.min(minArea, area);
                }
            }
        }
    }
    return minArea === Infinity ? 0 : minArea;
};
